from jsonb_to_recordset($json$[{"id":"che-st-186","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A converter is loaded with 14 g of nitrogen and 6 g of hydrogen for ammonia synthesis. The reagent that runs out first is","options":["nitrogen","hydrogen","both at the same instant","neither"],"answer_index":0,"explanation":"14 g N$_2$ is 0.50 mol and would need 1.5 mol H$_2$; 6 g H$_2$ is 3.0 mol, so nitrogen is consumed first.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-187","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Twelve grams of carbon are heated with 16 g of oxygen, forming only $\\mathrm{CO_2}$. The mass of carbon dioxide obtained is","options":["22 g","28 g","44 g","16 g"],"answer_index":0,"explanation":"1.0 mol C needs 1.0 mol (32 g) O$_2$; only 0.50 mol O$_2$ is present, so 0.50 mol (22 g) of $\\mathrm{CO_2}$ forms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-188","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Eight grams of hydrogen are burnt in 32 g of oxygen. After water has formed, the unused hydrogen weighs","options":["0 g","2 g","4 g","8 g"],"answer_index":2,"explanation":"1 mol O$_2$ consumes 2 mol (4 g) H$_2$; 8 g H$_2$ was supplied, so 4 g of hydrogen remains.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-189","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Two moles of $\\mathrm{SO_2}$ are oxidised with two moles of $\\mathrm{O_2}$ to $\\mathrm{SO_3}$. The oxygen left unreacted is","options":["0 mol","0.5 mol","1 mol","2 mol"],"answer_index":2,"explanation":"$2\\mathrm{SO_2}$ need only 1 mol O$_2$; of the 2 mol supplied, 1 mol remains.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-190","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Marble chips (25 g $\\mathrm{CaCO_3}$, M = 100) are treated with 14.6 g of HCl (M = 36.5) according to $\\mathrm{CaCO_3} + 2\\mathrm{HCl} \\rightarrow \\mathrm{CaCl_2} + \\mathrm{H_2O} + \\mathrm{CO_2}$. The mass of $\\mathrm{CO_2}$ that can escape is","options":["4.4 g","8.8 g","11.0 g","22.0 g"],"answer_index":1,"explanation":"0.25 mol carbonate would need 0.50 mol HCl, but only 0.40 mol HCl is present, so HCl limits and $0.20$ mol (8.8 g) of $\\mathrm{CO_2}$ forms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-191","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Theoretical yield is the mass of product calculated by assuming that","options":["the limiting reagent is completely converted as the equation is written","half the reactant is lost","no reaction occurs","the excess reagent alone reacts"],"answer_index":0,"explanation":"Theoretical yield is the stoichiometric maximum from the limiting reagent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"yield","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-192","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Percentage yield is obtained from the relation","options":["(theoretical / actual) $\\times 100$","(actual / theoretical) $\\times 100$","actual $-$ theoretical","theoretical $\\times$ actual"],"answer_index":1,"explanation":"Percent yield $= (\\text{actual yield}/\\text{theoretical yield}) \\times 100$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"yield","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-193","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"When the mass collected on the filter equals the mass predicted from the equation, the percentage yield is","options":["0%","50%","100%","200%"],"answer_index":2,"explanation":"Actual = theoretical gives a 100% yield.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"yield","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-194","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In the school laboratory the isolated product is usually lighter than the theoretical mass because of","options":["creation of extra atoms","incomplete reaction, side products and handling losses","a change in Avogadro’s number","the law of conservation of mass being false"],"answer_index":1,"explanation":"Real recoveries suffer from incomplete conversion, competing reactions and transfer losses.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"yield","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-195","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A statement that the yield is 100% means that","options":["no product was obtained","every mole of limiting reagent appeared in the isolated product as written","the excess reagent disappeared completely","the reaction was endothermic"],"answer_index":1,"explanation":"A quantitative isolation matching the stoichiometric prediction is a 100% yield.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"yield","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
